public class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each given Opportunity.
     * Returns the set of Opportunity Ids for which the Task could NOT be created.
     * An empty set means every task was created successfully.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // 1. Bulk-fetch all opportunities in a single SOQL.
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Name, OwnerId FROM Opportunity WHERE Id IN :opportunityIds]
        );

        // 2. Build the Task list. Track the opportunity Ids in the same order
        //    so we can map SaveResults back to their source opportunity.
        List<Task> tasks = new List<Task>();
        List<Id> orderedOppIds = new List<Id>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null) {
                // Id was supplied but no matching Opportunity exists.
                failedOpportunityIds.add(oppId);
                continue;
            }
            tasks.add(new Task(
                WhatId       = oppId,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            orderedOppIds.add(oppId);
        }

        if (tasks.isEmpty()) {
            return failedOpportunityIds;
        }

        // 3. Single DML statement. allOrNone = false lets individual
        //    validation-rule failures be reported per-record without
        //    rolling back the rest.
        List<Database.SaveResult> results = Database.insert(tasks, false);

        // 4. Collect the opportunity Ids whose task was rejected.
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(orderedOppIds[i]);
            }
        }

        return failedOpportunityIds;
    }
}
