public without sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Asynchronously recalculates the Rating on a single Account
     * based on its open pipeline.
     */
    @future
    public static void recalculate(Id accountId) {
        if (accountId == null) {
            return;
        }

        List<Opportunity> openOpps = [
            SELECT Amount
            FROM Opportunity
            WHERE AccountId = :accountId
              AND IsClosed = false
        ];

        String newRating;

        if (openOpps.isEmpty()) {
            newRating = 'Cold';
        } else {
            newRating = 'Warm'; // default: has open opps, none confirmed hot yet
            for (Opportunity opp : openOpps) {
                if (opp.Amount != null && opp.Amount >= HOT_THRESHOLD) {
                    newRating = 'Hot';
                    break;
                }
            }
        }

        Account acc = [SELECT Id, Rating FROM Account WHERE Id = :accountId];
        if (acc.Rating != newRating) {
            acc.Rating = newRating;
            update acc;
        }
    }
}
```

