    /**
     * Before-insert handler: default the Discount on new lines that don't have one
     * yet. Lines with an explicit discount (including 0) are left untouched.
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        // 1. Identify lines that need a default discount and collect their product IDs
        List<OpportunityLineItem> linesNeedingDiscount = new List<OpportunityLineItem>();
        Set<Id> productIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                linesNeedingDiscount.add(line);
                productIds.add(line.Product2Id);
            }
        }

        if (linesNeedingDiscount.isEmpty()) {
            return;
        }

        // 2. Bulk-fetch all needed products in a single SOQL query
        Map<Id, Product2> productMap = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
        );

        // 3. Apply the standard discount via PricingRules (no SOQL in the loop)
        for (OpportunityLineItem line : linesNeedingDiscount) {
            Product2 product = productMap.get(line.Product2Id);
            if (product != null) {
                line.Discount = PricingRules.standardDiscountForFamily(product.Family);
            }
        }
    }
